-- Remove broad defaults
REVOKE ALL ON DATABASE shop FROM PUBLIC;
REVOKE CREATE ON SCHEMA public FROM PUBLIC;

-- Group roles (cannot log in)
CREATE ROLE shop_rw NOLOGIN;
CREATE ROLE shop_ro NOLOGIN;
GRANT CONNECT ON DATABASE shop TO shop_rw, shop_ro;
GRANT USAGE ON SCHEMA public TO shop_rw, shop_ro;
GRANT SELECT, INSERT, UPDATE ON ALL TABLES IN SCHEMA public TO shop_rw;
GRANT SELECT ON ALL TABLES IN SCHEMA public TO shop_ro;

-- Login roles inherit from groups
CREATE ROLE app_rw LOGIN PASSWORD 'REPLACE_WITH_GENERATED_SECRET' CONNECTION LIMIT 20 IN ROLE shop_rw;
CREATE ROLE app_ro LOGIN PASSWORD 'REPLACE_WITH_GENERATED_SECRET' CONNECTION LIMIT 5 IN ROLE shop_ro;

